{
  "findings": [
    {
      "check_id": "CKV_AWS_378",
      "title": "Unhealthy target connection termination disabled",
      "resource": "aws_alb_target_group.pass",
      "severity": "MEDIUM",
      "explanation": "The target group explicitly keeps connections to unhealthy targets open, which can continue routing traffic to unhealthy or potentially compromised backends."
    }
  ],
  "patched_code": "resource \"aws_alb_target_group\" \"pass\" {\n  name     = \"tf-example-lb-nlb-tg\"\n  port     = 25\n  protocol = \"TCP\"\n  vpc_id   = aws_vpc.main.id\n\n  target_health_state {\n    enable_unhealthy_connection_termination = true\n  }\n}\n",
  "fix_summary": "Enabled unhealthy connection termination so the load balancer stops maintaining connections to targets that fail health checks."
}
